//! Minimal HTTP/1.1 message types and request-head parsing.

const CRLF: &[u8] = b"\r\n";
const HEAD_TERMINATOR: &[u8] = b"\r\n\r\n";

/// A parsed HTTP request.
#[derive(Debug, Default, Clone)]
pub struct Request {
    pub method: String,
    pub target: String,
    pub headers: Vec<(String, String)>,
    pub body: Vec<u8>,
}

impl Request {
    /// Case-insensitive header lookup; returns the first match.
    pub fn header(&self, name: &str) -> Option<&str> {
        self.headers
            .iter()
            .find(|(key, _)| key.eq_ignore_ascii_case(name))
            .map(|(_, value)| value.as_str())
    }
}

/// An HTTP response. `Content-Length` and `Connection: close` are added on
/// serialization.
#[derive(Debug, Clone)]
pub struct Response {
    pub status: u16,
    pub headers: Vec<(String, String)>,
    pub body: Vec<u8>,
}

impl Response {
    pub fn new(status: u16, headers: Vec<(String, String)>, body: Vec<u8>) -> Self {
        Self {
            status,
            headers,
            body,
        }
    }

    /// A response with no headers and an empty body.
    pub fn empty(status: u16) -> Self {
        Self::new(status, Vec::new(), Vec::new())
    }

    /// A `text/plain` response.
    pub fn text(status: u16, body: impl Into<String>) -> Self {
        Self::new(
            status,
            vec![("Content-Type".into(), "text/plain; charset=utf-8".into())],
            body.into().into_bytes(),
        )
    }

    pub fn with_header(mut self, name: impl Into<String>, value: impl Into<String>) -> Self {
        self.headers.push((name.into(), value.into()));
        self
    }

    /// Serializes the status line and headers, including `Content-Length` and
    /// `Connection: close`. The body is not included.
    pub fn serialize_head(&self) -> Vec<u8> {
        use std::fmt::Write as _;

        let mut out = String::with_capacity(128 + self.headers.len() * 32);
        let _ = write!(
            out,
            "HTTP/1.1 {} {}\r\n",
            self.status,
            reason_phrase(self.status)
        );
        for (key, value) in &self.headers {
            let _ = write!(out, "{key}: {value}\r\n");
        }
        // 204 responses must not carry a body; Content-Length is omitted there.
        if self.status != 204 {
            let _ = write!(out, "Content-Length: {}\r\n", self.body.len());
        }
        out.push_str("Connection: close\r\n\r\n");
        out.into_bytes()
    }
}

pub fn reason_phrase(status: u16) -> &'static str {
    match status {
        200 => "OK",
        201 => "Created",
        204 => "No Content",
        400 => "Bad Request",
        404 => "Not Found",
        405 => "Method Not Allowed",
        408 => "Request Timeout",
        411 => "Length Required",
        413 => "Content Too Large",
        431 => "Request Header Fields Too Large",
        500 => "Internal Server Error",
        501 => "Not Implemented",
        505 => "HTTP Version Not Supported",
        _ => "Unknown",
    }
}

/// Result of parsing the request head (request line + headers).
#[derive(Debug)]
pub struct ParsedHead {
    pub request: Request,
    /// Bytes consumed, including the final CRLFCRLF.
    pub head_size: usize,
}

/// Why a request head could not be parsed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HeadError {
    /// The terminating blank line has not been received yet.
    Incomplete,
    /// The head is complete but malformed.
    Malformed,
}

pub fn find(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    haystack.windows(needle.len()).position(|w| w == needle)
}

fn is_token_char(c: u8) -> bool {
    c.is_ascii_alphanumeric() || b"!#$%&'*+-.^_`|~".contains(&c)
}

fn is_token(s: &[u8]) -> bool {
    !s.is_empty() && s.iter().copied().all(is_token_char)
}

fn trim(s: &[u8]) -> &[u8] {
    let is_ws = |c: &u8| *c == b' ' || *c == b'\t';
    let Some(begin) = s.iter().position(|c| !is_ws(c)) else {
        return &[];
    };
    let end = s.iter().rposition(|c| !is_ws(c)).map_or(begin, |e| e + 1);
    &s[begin..end]
}

fn split_once<'a>(s: &'a [u8], sep: &[u8]) -> (&'a [u8], Option<&'a [u8]>) {
    match find(s, sep) {
        Some(pos) => (&s[..pos], Some(&s[pos + sep.len()..])),
        None => (s, None),
    }
}

fn lossy(s: &[u8]) -> String {
    String::from_utf8_lossy(s).into_owned()
}

/// Parses the request head at the start of `data`.
pub fn parse_head(data: &[u8]) -> Result<ParsedHead, HeadError> {
    let head_end = find(data, HEAD_TERMINATOR).ok_or(HeadError::Incomplete)?;
    let head = &data[..head_end];

    // Request line: METHOD SP request-target SP HTTP-version
    let (request_line, mut rest) = split_once(head, CRLF);
    let mut parts = request_line.splitn(3, |&c| c == b' ');
    let (Some(method), Some(target), Some(version)) = (parts.next(), parts.next(), parts.next())
    else {
        return Err(HeadError::Malformed);
    };
    if !is_token(method) || target.is_empty() || !version.starts_with(b"HTTP/1.") {
        return Err(HeadError::Malformed);
    }

    let mut request = Request {
        method: lossy(method),
        target: lossy(target),
        ..Request::default()
    };

    // Header fields.
    while let Some(remaining) = rest.filter(|r| !r.is_empty()) {
        let (line, next) = split_once(remaining, CRLF);
        rest = next;

        let colon = line
            .iter()
            .position(|&c| c == b':')
            .ok_or(HeadError::Malformed)?;
        let name = &line[..colon];
        if !is_token(name) {
            return Err(HeadError::Malformed);
        }
        request
            .headers
            .push((lossy(name), lossy(trim(&line[colon + 1..]))));
    }

    Ok(ParsedHead {
        request,
        head_size: head_end + HEAD_TERMINATOR.len(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_request_line_and_headers() {
        let data = b"PUT /kv/a HTTP/1.1\r\nHost: x\r\nContent-Length:  5 \r\n\r\nhello";
        let parsed = parse_head(data).unwrap();
        assert_eq!(parsed.head_size, data.len() - 5);
        assert_eq!(parsed.request.method, "PUT");
        assert_eq!(parsed.request.target, "/kv/a");
        assert_eq!(parsed.request.header("content-length"), Some("5"));
    }

    #[test]
    fn rejects_malformed_heads() {
        assert_eq!(
            parse_head(b"GET /\r\n\r\n").unwrap_err(),
            HeadError::Malformed
        );
        assert_eq!(
            parse_head(b"GET / FTP/1.0\r\n\r\n").unwrap_err(),
            HeadError::Malformed
        );
        assert_eq!(
            parse_head(b"GET / HTTP/1.1\r\nBad Header: x\r\n\r\n").unwrap_err(),
            HeadError::Malformed
        );
        assert_eq!(
            parse_head(b"GET / HTTP/1.1\r\n").unwrap_err(),
            HeadError::Incomplete
        );
    }

    #[test]
    fn omits_content_length_for_204() {
        let head = String::from_utf8(Response::empty(204).serialize_head()).unwrap();
        assert!(!head.contains("Content-Length"));
        let head = String::from_utf8(Response::text(200, "ok").serialize_head()).unwrap();
        assert!(head.contains("Content-Length: 2\r\n"));
    }
}

//! kvhttp: an in-memory HTTP/1.1 key-value server.

mod http;
mod routes;
mod server;
mod store;

use std::process::ExitCode;

use server::{Server, ServerOptions};
use store::KvStore;

fn parse_port(arg: &str) -> Option<u16> {
    if arg.is_empty() || !arg.bytes().all(|c| c.is_ascii_digit()) {
        return None;
    }
    arg.parse().ok().filter(|&port| port != 0)
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().collect();
    let [_, port_arg] = args.as_slice() else {
        let program = args.first().map_or("app", String::as_str);
        eprintln!("usage: {program} <port>");
        return ExitCode::from(2);
    };
    let Some(port) = parse_port(port_arg) else {
        eprintln!("invalid port: {port_arg}");
        return ExitCode::from(2);
    };

    let store = KvStore::new();
    let options = ServerOptions {
        port,
        ..ServerOptions::default()
    };
    match Server::bind(options, move |request| routes::route(&store, request)) {
        Ok(server) => server.run(),
        Err(e) => {
            eprintln!("fatal: bind: {e}");
            ExitCode::FAILURE
        }
    }
}

//! The key-value HTTP API.

use crate::http::{Request, Response};
use crate::store::{KvStore, PutResult};

const KV_PREFIX: &str = "/kv/";
const MAX_KEY_LENGTH: usize = 64;

/// Returns true if `key` matches `[A-Za-z0-9_-]{1,64}`.
pub fn is_valid_key(key: &str) -> bool {
    (1..=MAX_KEY_LENGTH).contains(&key.len())
        && key
            .bytes()
            .all(|c| c.is_ascii_alphanumeric() || c == b'_' || c == b'-')
}

/// Dispatches a request against the key-value API.
pub fn route(store: &KvStore, request: Request) -> Response {
    match request.target.as_str() {
        "/health" => handle_health(&request),
        "/kv" => handle_list(store, &request),
        path => match path.strip_prefix(KV_PREFIX) {
            Some(key) => {
                let key = key.to_owned();
                handle_key(store, request, key)
            }
            None => not_found(),
        },
    }
}

fn not_found() -> Response {
    Response::text(404, "not found")
}

fn method_not_allowed(allow: &str) -> Response {
    Response::text(405, "Method Not Allowed").with_header("Allow", allow)
}

fn handle_health(request: &Request) -> Response {
    match request.method.as_str() {
        "GET" => Response::text(200, "ok"),
        _ => method_not_allowed("GET"),
    }
}

fn handle_list(store: &KvStore, request: &Request) -> Response {
    if request.method != "GET" {
        return method_not_allowed("GET");
    }
    // Keys are restricted to [A-Za-z0-9_-], so no JSON escaping is required.
    let quoted: Vec<String> = store
        .keys()
        .iter()
        .map(|key| format!("\"{key}\""))
        .collect();
    let body = format!("[{}]", quoted.join(","));
    Response::new(
        200,
        vec![("Content-Type".into(), "application/json".into())],
        body.into_bytes(),
    )
}

fn handle_key(store: &KvStore, request: Request, key: String) -> Response {
    if !is_valid_key(&key) {
        return Response::text(400, "invalid key");
    }
    match request.method.as_str() {
        "GET" => match store.get(&key) {
            Some(value) => Response::new(
                200,
                vec![("Content-Type".into(), "application/octet-stream".into())],
                value,
            ),
            None => not_found(),
        },
        "PUT" => match store.put(key, request.body) {
            PutResult::Created => Response::empty(201),
            PutResult::Replaced => Response::empty(200),
        },
        "DELETE" => {
            if store.remove(&key) {
                Response::empty(204)
            } else {
                not_found()
            }
        }
        _ => method_not_allowed("GET, PUT, DELETE"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn req(method: &str, target: &str, body: &[u8]) -> Request {
        Request {
            method: method.into(),
            target: target.into(),
            body: body.to_vec(),
            ..Request::default()
        }
    }

    #[test]
    fn key_validation() {
        assert!(is_valid_key("a-Z_09"));
        assert!(is_valid_key(&"k".repeat(64)));
        assert!(!is_valid_key(&"k".repeat(65)));
        assert!(!is_valid_key(""));
        assert!(!is_valid_key("a/b"));
        assert!(!is_valid_key("a.b"));
    }

    #[test]
    fn routing() {
        let store = KvStore::new();
        assert_eq!(route(&store, req("GET", "/health", b"")).status, 200);
        assert_eq!(route(&store, req("POST", "/health", b"")).status, 405);
        assert_eq!(route(&store, req("GET", "/nope", b"")).status, 404);
        assert_eq!(route(&store, req("GET", "/kv/", b"")).status, 400);
        assert_eq!(route(&store, req("PATCH", "/kv/a", b"")).status, 405);
        assert_eq!(route(&store, req("PUT", "/kv/b", b"x")).status, 201);
        assert_eq!(route(&store, req("PUT", "/kv/a", b"y")).status, 201);
        assert_eq!(route(&store, req("PUT", "/kv/a", b"z")).status, 200);
        assert_eq!(route(&store, req("GET", "/kv/a", b"")).body, b"z");
        assert_eq!(route(&store, req("GET", "/kv", b"")).body, br#"["a","b"]"#);
        assert_eq!(route(&store, req("DELETE", "/kv/a", b"")).status, 204);
        assert_eq!(route(&store, req("DELETE", "/kv/a", b"")).status, 404);
        assert_eq!(route(&store, req("GET", "/kv/a", b"")).status, 404);
    }
}

//! Minimal HTTP/1.1 server: one request per connection, one thread per
//! connection.

use std::io::{self, ErrorKind, Read, Write};
use std::net::{Ipv4Addr, Shutdown, SocketAddr, TcpListener, TcpStream};
use std::panic::{self, AssertUnwindSafe};
use std::sync::Arc;
use std::thread;
use std::time::Duration;

use crate::http::{self, HeadError, Request, Response};

#[derive(Debug, Clone)]
pub struct ServerOptions {
    pub port: u16,
    pub max_head_bytes: usize,
    pub max_body_bytes: usize,
    pub io_timeout: Duration,
}

impl Default for ServerOptions {
    fn default() -> Self {
        Self {
            port: 8080,
            max_head_bytes: 64 * 1024,
            max_body_bytes: 1024 * 1024,
            io_timeout: Duration::from_secs(10),
        }
    }
}

/// Why reading a request failed.
#[derive(Debug)]
enum ReadError {
    /// The peer misbehaved in a way that should produce this HTTP status.
    Http(u16),
    /// The connection is unusable (peer closed, I/O error).
    Closed,
}

type ReadResult<T> = Result<T, ReadError>;

const READ_CHUNK: usize = 64 * 1024;
const MAX_DRAIN_BYTES: usize = 16 * 1024 * 1024;
const LINGER_TIMEOUT: Duration = Duration::from_secs(1);
const ACCEPT_BACKOFF: Duration = Duration::from_millis(10);

struct Connection<'a> {
    stream: TcpStream,
    options: &'a ServerOptions,
    buffer: Vec<u8>,
}

impl<'a> Connection<'a> {
    fn new(stream: TcpStream, options: &'a ServerOptions) -> Self {
        Self {
            stream,
            options,
            buffer: Vec::new(),
        }
    }

    fn read_request(&mut self) -> ReadResult<Request> {
        let head = loop {
            match http::parse_head(&self.buffer) {
                Ok(head) => break head,
                Err(HeadError::Malformed) => return Err(ReadError::Http(400)),
                Err(HeadError::Incomplete) => {
                    if self.buffer.len() > self.options.max_head_bytes {
                        return Err(ReadError::Http(431));
                    }
                    if !self.fill()? {
                        return Err(ReadError::Closed);
                    }
                }
            }
        };
        self.buffer.drain(..head.head_size);
        let mut request = head.request;
        request.body = self.read_body(&request)?;
        Ok(request)
    }

    fn send_response(&mut self, response: &Response, include_body: bool) -> io::Result<()> {
        self.stream.write_all(&response.serialize_head())?;
        if include_body {
            self.stream.write_all(&response.body)?;
        }
        self.stream.flush()
    }

    /// Half-closes the socket and discards any remaining input so the client
    /// sees the response rather than a reset.
    fn linger_close(&mut self) {
        let _ = self.stream.shutdown(Shutdown::Write);
        let _ = self.stream.set_read_timeout(Some(LINGER_TIMEOUT));
        let mut scratch = [0u8; 16 * 1024];
        let mut drained = 0;
        while drained < MAX_DRAIN_BYTES {
            match self.stream.read(&mut scratch) {
                Ok(0) => break,
                Ok(n) => drained += n,
                Err(e) if e.kind() == ErrorKind::Interrupted => {}
                Err(_) => break,
            }
        }
    }

    /// Reads more bytes into the buffer; returns `false` on EOF.
    fn fill(&mut self) -> ReadResult<bool> {
        let start = self.buffer.len();
        self.buffer.resize(start + READ_CHUNK, 0);
        let result = loop {
            match self.stream.read(&mut self.buffer[start..]) {
                Err(e) if e.kind() == ErrorKind::Interrupted => {}
                other => break other,
            }
        };
        self.buffer.truncate(start + *result.as_ref().unwrap_or(&0));
        match result {
            Ok(n) => Ok(n > 0),
            Err(e) => match e.kind() {
                ErrorKind::WouldBlock | ErrorKind::TimedOut => Err(ReadError::Http(408)),
                _ => Err(ReadError::Closed),
            },
        }
    }

    /// Ensures at least `n` bytes are buffered.
    fn require(&mut self, n: usize) -> ReadResult<()> {
        while self.buffer.len() < n {
            if !self.fill()? {
                return Err(ReadError::Http(400));
            }
        }
        Ok(())
    }

    fn take(&mut self, n: usize) -> ReadResult<Vec<u8>> {
        self.require(n)?;
        let rest = self.buffer.split_off(n);
        Ok(std::mem::replace(&mut self.buffer, rest))
    }

    fn read_line(&mut self) -> ReadResult<Vec<u8>> {
        loop {
            if let Some(pos) = http::find(&self.buffer, b"\r\n") {
                let mut line = self.take(pos + 2)?;
                line.truncate(pos);
                return Ok(line);
            }
            if self.buffer.len() > self.options.max_head_bytes || !self.fill()? {
                return Err(ReadError::Http(400));
            }
        }
    }

    fn read_body(&mut self, request: &Request) -> ReadResult<Vec<u8>> {
        if let Some(te) = request.header("Transfer-Encoding") {
            if !te.eq_ignore_ascii_case("chunked") {
                return Err(ReadError::Http(501));
            }
            return self.read_chunked_body();
        }
        let Some(length) = request.header("Content-Length") else {
            return Ok(Vec::new());
        };
        let length = parse_content_length(length)?;
        if length > self.options.max_body_bytes {
            return Err(ReadError::Http(413));
        }
        self.take(length)
    }

    fn read_chunked_body(&mut self) -> ReadResult<Vec<u8>> {
        let mut body = Vec::new();
        loop {
            let line = self.read_line()?;
            let size_text = line.split(|&c| c == b';').next().unwrap_or_default();
            let size = parse_chunk_size(size_text).ok_or(ReadError::Http(400))?;
            if size == 0 {
                // Discard trailer fields up to the terminating blank line.
                while !self.read_line()?.is_empty() {}
                return Ok(body);
            }
            if size > self.options.max_body_bytes - body.len() {
                return Err(ReadError::Http(413));
            }
            body.extend_from_slice(&self.take(size)?);
            if !self.read_line()?.is_empty() {
                return Err(ReadError::Http(400));
            }
        }
    }
}

/// Parses a `Content-Length` value: decimal digits only.
fn parse_content_length(text: &str) -> ReadResult<usize> {
    if text.is_empty() || !text.bytes().all(|c| c.is_ascii_digit()) {
        return Err(ReadError::Http(400));
    }
    // Only overflow can fail here; treat it as an oversized body.
    text.parse().map_err(|_| ReadError::Http(413))
}

/// Parses a chunk size: hexadecimal digits only.
fn parse_chunk_size(text: &[u8]) -> Option<usize> {
    if text.is_empty() || !text.iter().all(u8::is_ascii_hexdigit) {
        return None;
    }
    usize::from_str_radix(std::str::from_utf8(text).ok()?, 16).ok()
}

/// One-request-per-connection HTTP server listening on 127.0.0.1.
pub struct Server<H> {
    options: Arc<ServerOptions>,
    handler: Arc<H>,
    listener: TcpListener,
}

impl<H> Server<H>
where
    H: Fn(Request) -> Response + Send + Sync + 'static,
{
    /// Binds and listens on the configured port.
    pub fn bind(options: ServerOptions, handler: H) -> io::Result<Self> {
        let listener = TcpListener::bind(SocketAddr::from((Ipv4Addr::LOCALHOST, options.port)))?;
        Ok(Self {
            options: Arc::new(options),
            handler: Arc::new(handler),
            listener,
        })
    }

    /// Accept loop; does not return under normal operation.
    pub fn run(&self) -> ! {
        loop {
            let stream = match self.listener.accept() {
                Ok((stream, _)) => stream,
                Err(e) => {
                    if !matches!(
                        e.kind(),
                        ErrorKind::Interrupted | ErrorKind::ConnectionAborted
                    ) {
                        eprintln!("accept: {e}");
                        // Typically descriptor exhaustion: back off briefly before retrying.
                        thread::sleep(ACCEPT_BACKOFF);
                    }
                    continue;
                }
            };
            let options = Arc::clone(&self.options);
            let handler = Arc::clone(&self.handler);
            if let Err(e) = thread::Builder::new()
                .spawn(move || handle_connection(stream, &options, handler.as_ref()))
            {
                eprintln!("failed to spawn connection thread: {e}");
            }
        }
    }
}

fn configure(stream: &TcpStream, timeout: Duration) -> io::Result<()> {
    stream.set_read_timeout(Some(timeout))?;
    stream.set_write_timeout(Some(timeout))?;
    stream.set_nodelay(true)
}

fn handle_connection<H>(stream: TcpStream, options: &ServerOptions, handler: &H)
where
    H: Fn(Request) -> Response,
{
    if let Err(e) = configure(&stream, options.io_timeout) {
        eprintln!("socket setup: {e}");
        return;
    }
    let mut conn = Connection::new(stream, options);

    let (response, include_body) = match conn.read_request() {
        Ok(request) => {
            let include_body = request.method != "HEAD";
            let response = panic::catch_unwind(AssertUnwindSafe(|| handler(request)))
                .unwrap_or_else(|_| Response::text(500, "Internal Server Error"));
            (response, include_body)
        }
        Err(ReadError::Http(status)) => (Response::text(status, http::reason_phrase(status)), true),
        // Peer went away; nothing more to do.
        Err(ReadError::Closed) => return,
    };

    if conn.send_response(&response, include_body).is_ok() {
        conn.linger_close();
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn content_length_parsing() {
        assert_eq!(parse_content_length("12").unwrap(), 12);
        assert!(matches!(
            parse_content_length(""),
            Err(ReadError::Http(400))
        ));
        assert!(matches!(
            parse_content_length("+1"),
            Err(ReadError::Http(400))
        ));
        assert!(matches!(
            parse_content_length("1 2"),
            Err(ReadError::Http(400))
        ));
        assert!(matches!(
            parse_content_length("99999999999999999999999"),
            Err(ReadError::Http(413))
        ));
    }

    #[test]
    fn chunk_size_parsing() {
        assert_eq!(parse_chunk_size(b"1aF"), Some(0x1af));
        assert_eq!(parse_chunk_size(b""), None);
        assert_eq!(parse_chunk_size(b"+1"), None);
        assert_eq!(parse_chunk_size(b"0x1"), None);
    }
}

//! Thread-safe in-memory key-value store.

use std::collections::BTreeMap;
use std::sync::{PoisonError, RwLock, RwLockReadGuard, RwLockWriteGuard};

/// Outcome of [`KvStore::put`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PutResult {
    Created,
    Replaced,
}

/// Keys are kept ordered so that listing them sorted is a linear walk.
#[derive(Debug, Default)]
pub struct KvStore {
    data: RwLock<BTreeMap<String, Vec<u8>>>,
}

impl KvStore {
    pub fn new() -> Self {
        Self::default()
    }

    // The map is never left in an inconsistent state, so a poisoned lock is
    // safe to keep using.
    fn read(&self) -> RwLockReadGuard<'_, BTreeMap<String, Vec<u8>>> {
        self.data.read().unwrap_or_else(PoisonError::into_inner)
    }

    fn write(&self) -> RwLockWriteGuard<'_, BTreeMap<String, Vec<u8>>> {
        self.data.write().unwrap_or_else(PoisonError::into_inner)
    }

    pub fn put(&self, key: String, value: Vec<u8>) -> PutResult {
        match self.write().insert(key, value) {
            Some(_) => PutResult::Replaced,
            None => PutResult::Created,
        }
    }

    pub fn get(&self, key: &str) -> Option<Vec<u8>> {
        self.read().get(key).cloned()
    }

    pub fn remove(&self, key: &str) -> bool {
        self.write().remove(key).is_some()
    }

    /// All keys in ascending order.
    pub fn keys(&self) -> Vec<String> {
        self.read().keys().cloned().collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn crud() {
        let store = KvStore::new();
        assert_eq!(store.put("b".into(), b"1".to_vec()), PutResult::Created);
        assert_eq!(store.put("b".into(), b"2".to_vec()), PutResult::Replaced);
        store.put("a".into(), Vec::new());
        assert_eq!(store.get("b").as_deref(), Some(&b"2"[..]));
        assert_eq!(store.keys(), ["a", "b"]);
        assert!(store.remove("b"));
        assert!(!store.remove("b"));
        assert_eq!(store.get("b"), None);
    }
}
